#include <stl_tree.h>

class stringx
{
  char data[8];
};

class vr_pmesh;

template <class T> class instance_bank
{
public:
  struct ref_t
  {
    stringx label;
    T *ptr;
    unsigned int count;
  };

  struct less_by_label
  {
    bool operator()(const ref_t *a, const ref_t *b) const
    {
      return a->ptr < b->ptr;
    }
  };
};

typedef instance_bank<vr_pmesh>::ref_t *value_type;
typedef _Rb_tree<value_type, value_type, _Identity<value_type>,
                 instance_bank<vr_pmesh>::less_by_label,
                 __malloc_alloc_template<0> > tree_type;

template tree_type::iterator tree_type::_M_insert(
  _Rb_tree_node_base *, _Rb_tree_node_base *, value_type const &);
